create table if not exists private.immortal_battle_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,channel text not null check(channel in('formal','test')),source text not null check(source in('domain','expedition')),player_power numeric not null check(player_power>0),status text not null default'pending'check(status in('pending','finished','expired')),won boolean,created_at timestamptz not null default now(),finished_at timestamptz);create index if not exists immortal_battle_attempts_user_idx on private.immortal_battle_attempts(user_id,channel,created_at desc);alter table private.immortal_battle_attempts enable row level security;revoke all on private.immortal_battle_attempts from public,anon,authenticated;

create or replace function public.player_immortal_investigate(p_channel text,p_site text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;first_visit boolean;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_site not in('array','stele')or p_request_id is null then raise exception '仙界調查請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的仙界調查請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-platform-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;first_visit:=not s.investigated? p_site;if first_visit then update private.player_immortal_states set investigated=investigated||jsonb_build_array(p_site),residual_source=residual_source+case when p_site='array'then 3 else 0 end,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;end if;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_investigated',p_request_id,jsonb_build_object('site',p_site,'firstVisit',first_visit));return jsonb_build_object('firstVisit',first_visit,'immortal',private.immortal_snapshot(s));end$$;

create or replace function public.player_immortal_expedition_command(p_channel text,p_action text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;old_node integer;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_action not in('start','advance')or p_request_id is null then raise exception '古臺遠征請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的古臺遠征請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-platform-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if not s.expedition_unlocked then raise exception '飛升古臺外圍尚未解鎖';end if;if s.expedition_day is distinct from private.immortal_day()then s.expedition_day:=private.immortal_day();s.expedition_used:=0;end if;old_node:=s.expedition_node;if p_action='start'then if s.expedition_active then raise exception '遠征已在進行中';end if;if s.expedition_used>=3 then raise exception '今日遠征次數已盡';end if;update private.player_immortal_states set expedition_day=s.expedition_day,expedition_used=s.expedition_used+1,expedition_active=true,expedition_node=1,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;else if not s.expedition_active or old_node not in(1,3,4)then raise exception '目前遠征節點不可推進';end if;if old_node=1 then update private.player_immortal_states set residual_source=residual_source+3,expedition_node=2,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;elsif old_node=3 then update private.player_immortal_states set residual_source=residual_source+1,expedition_node=4,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;else update private.player_immortal_states set expedition_active=false,expedition_node=0,expedition_runs=expedition_runs+1,outer_route_cleared=true,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;end if;end if;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_expedition_'||p_action,p_request_id,jsonb_build_object('oldNode',old_node,'node',s.expedition_node));return private.immortal_snapshot(s);end$$;

create or replace function public.player_immortal_battle_start(p_channel text,p_source text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());s private.player_immortal_states;a private.player_ascension_states;profile public.arena_profiles;attempt uuid;power numeric;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_source not in('domain','expedition')or p_request_id is null then raise exception '仙界戰鬥請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的仙界戰鬥請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-battle-'||p_channel));select * into s from private.player_immortal_states where user_id=uid and channel=p_channel;select * into a from private.player_ascension_states where user_id=uid and channel=p_channel;if s.user_id is null or not a.ascended then raise exception '尚未踏入仙界';end if;if p_source='domain'and(not s.investigated?'array'or not s.investigated?'stele')then raise exception '先完成古臺調查';end if;if p_source='expedition'and(not s.expedition_active or s.expedition_node<>2)then raise exception '目前沒有遠征戰鬥';end if;select * into profile from public.arena_profiles where user_id=uid and channel=p_channel;if profile.user_id is null then raise exception '請先同步戰鬥屬性';end if;perform private.arena_validate_snapshot(profile.snapshot);perform private.arena_validate_server_progression(uid,p_channel,profile.snapshot);power:=(profile.snapshot->>'combat_power')::numeric;update private.immortal_battle_attempts set status='expired'where user_id=uid and channel=p_channel and status='pending';insert into private.immortal_battle_attempts(user_id,channel,source,player_power)values(uid,p_channel,p_source,power)returning id into attempt;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_battle_started',p_request_id,jsonb_build_object('attemptId',attempt,'source',p_source));return jsonb_build_object('attemptId',attempt,'immortal',private.immortal_snapshot(s));end$$;

create or replace function public.player_immortal_battle_finish(p_channel text,p_attempt_id uuid,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());b private.immortal_battle_attempts;s private.player_immortal_states;server_won boolean;chance numeric:=.65;first_win boolean:=false;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test')or p_attempt_id is null or p_request_id is null then raise exception '仙界戰鬥結算請求不正確';end if;if exists(select 1 from private.player_state_events where user_id=uid and channel=p_channel and request_id=p_request_id)then raise exception '重複的仙界戰鬥結算請求';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-immortal-battle-'||p_channel));select * into b from private.immortal_battle_attempts where id=p_attempt_id and user_id=uid and channel=p_channel for update;select * into s from private.player_immortal_states where user_id=uid and channel=p_channel for update;if b.id is null or b.status<>'pending'or b.created_at<now()-interval'45 minutes'then raise exception '仙界戰鬥已失效';end if;if b.created_at>now()-interval'3 seconds'then raise exception '戰鬥尚未完成';end if;if b.source='expedition'and(not s.expedition_active or s.expedition_node<>2)then raise exception '遠征戰鬥進度衝突';end if;server_won:=random()<chance;update private.immortal_battle_attempts set status='finished',won=server_won,finished_at=now()where id=b.id;if server_won and b.source='domain'then first_win:=not s.first_battle_won;update private.player_immortal_states set first_battle_won=true,expedition_unlocked=true,barren_traces=barren_traces+case when first_win then 2 else 0 end,investigated=case when investigated?'gate'then investigated else investigated||'"gate"'::jsonb end,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;elsif server_won then update private.player_immortal_states set barren_traces=barren_traces+1,expedition_node=3,revision=revision+1,updated_at=now()where user_id=uid and channel=p_channel returning * into s;end if;insert into private.player_state_events(user_id,channel,revision,event_type,request_id,payload)values(uid,p_channel,s.revision,'immortal_battle_resolved',p_request_id,jsonb_build_object('attemptId',b.id,'source',b.source,'won',server_won,'firstWin',first_win));return jsonb_build_object('won',server_won,'firstWin',first_win,'immortal',private.immortal_snapshot(s));end$$;

revoke execute on function public.player_immortal_investigate(text,text,uuid),public.player_immortal_expedition_command(text,text,uuid),public.player_immortal_battle_start(text,text,uuid),public.player_immortal_battle_finish(text,uuid,uuid)from public,anon;grant execute on function public.player_immortal_investigate(text,text,uuid),public.player_immortal_expedition_command(text,text,uuid),public.player_immortal_battle_start(text,text,uuid),public.player_immortal_battle_finish(text,uuid,uuid)to authenticated;
